package sohal.lld.battleship.logging;import java.util.ArrayList;import java.util.List;public class GameLogger implements GameObserver {    private final List<GameEvent> events = new ArrayList<>();    @Override public void onEvent(GameEvent event) { events.add(event); }    public List<GameEvent> getEvents() { return List.copyOf(events); }    public void printLog() { events.forEach(e -> System.out.println(e.getMessage())); }}